using Earthward.Domain;using Earthward.Combat;using Godot;
internal static class NaturalOpening
{
 sealed class Surface:ICombatSurface{public DefenseState Game=null!;public IReadOnlyList<DataMap> GetFactorySites(){var list=new List<DataMap>();int familyIndex=0;foreach(string family in new[]{"interceptor","missile","laser"}){for(int i=0;i<Game.Buildings.I(family);i++){int front=family=="interceptor"?Math.Max(0,i-1):i;var n=InvasionDirector.LocalDirections[front%8].Normalized();if(family=="interceptor"&&i==1)n=n.Rotated(Vector3.Up,-.14f).Normalized();var tangent=Vector3.Up.Cross(n).Normalized();if(tangent.LengthSquared()<.01)tangent=Vector3.Right;list.Add(new(){["site_id"]=(long)(familyIndex*1000+i),["kind"]=family,["normal"]=n,["launch_position"]=n*4.108f,["launch_direction"]=tangent});}familyIndex++;}return list;}public Vector3 SurfaceToSpace(Vector3 n,double a)=>n*(float)(4+a);public Vector3 SpaceToSurface(Vector3 p)=>p.Normalized();public IReadOnlyList<Vector3> GetOccupiedSurfaceNormals()=>Array.Empty<Vector3>();}
 static readonly string[] Early={"K_S01","I_S03","D_S01","K_S02","D_S02"},Mid={"K_A1","D_A1","I_S01","I_S02","I_S04","I_S05","C_S01","C_S02","M_S01","L_S01","C_A1","D_S03","M_S02","L_S02"},Long={"K_S06","K_S07","D_S06","D_S07","I_S08","M_S06","L_S06","C_S06","C_N1","C_A1","C_G1","K_N1","K_G1","M_A1","M_G1","D_N1","D_G1","I_N1","I_N2","I_G1","C_N2","C_A2","C_S11","C_A3","C_S16","C_G2","M_N2","M_S11","M_N3","L_N2","L_S11","L_N3","K_N2","K_S11","K_N3","L_A1","L_G1","I_S13","I_N3","I_A1","I_A2","I_S11","I_A3","I_S16","I_G2"};
 public static void Run(){var runs=new List<DataMap>();foreach(int seed in new[]{11,9918,49127}){var g=new DefenseState();var start=g.Serialize();start["run_id"]="csharp-natural-seed"+seed;if(!g.Restore(start))throw new Exception("new natural state");g.FactoryPerks.ImportSnapshot(new FactoryPerks().Snapshot());var b=new Battlefield(g,new Surface{Game=g});b.Random.Seed=(ulong)seed;long firstPerk=-1;g.FactoryPerkRewarded+=_=>{if(firstPerk<0)firstPerk=g.Wave;};var actions=new DataMap();var purchases=new List<object?>();var waves=new List<object?>();double time=0,nextAction=0;long reported=0;
 bool Buy(string id){if(!g.GetGroupStatus(id).B("can_purchase")||!g.PurchaseGroup(id))return false;purchases.Add(new DataMap{["id"]=id,["time"]=Math.Floor(time/.1+.5)*.1,["wave"]=g.Wave,["science"]=Math.Floor(g.Science/.1+.5)*.1});return true;}
 void Act(){if(g.EarthHp<=0)return;foreach(var entry in new[]{new[]{"interceptor","a_kinetic_core","f_kinetic_quality"},new[]{"missile","a_missile_charge","f_missile_warhead"},new[]{"laser","a_laser_crystal","f_laser_lattice"}})for(int i=1;i<=2;i++){string layer=i==1?"aircraft":"factory",id=entry[i];if(g.FactoryPerks.IsUnlocked(id)&&g.FactoryPerks.SlotsFor(entry[0],-1,layer)[0]!=id)g.FactoryPerks.Equip(entry[0],-1,0,id,layer);if(id=="a_kinetic_core"&&g.FactoryPerks.GetLevel(id)<3&&g.FactoryPerks.UpgradeLockReason(id)=="")g.FactoryPerks.Upgrade(id);}if(b.EmpCooldown<=0&&(b.Enemies.Any(e=>e.S("kind")=="boss")||b.Enemies.Count>=12)&&b.UseEmp())actions["emp"]=actions.I("emp")+1;if(g.EarthHp<75&&g.CanRepair()&&g.Repair())actions["repairs"]=actions.I("repairs")+1;if(g.Buildings.I("interceptor")<3&&g.CanBuild("interceptor")){g.Build("interceptor");return;}foreach(string id in Early)if(!g.HasResearch(id)&&Buy(id))return;if(g.Wave>=4&&!g.HasResearch("M_N1")){Buy("M_N1");return;}int fronts=b.GetInvasionFronts().Count;if(g.HasResearch("M_N1")&&g.Buildings.I("missile")<Math.Max(2,fronts)&&g.CanBuild("missile")){g.Build("missile");return;}if(g.CompletedWaves>=10&&!g.HasResearch("L_N1")){Buy("L_N1");return;}if(g.HasResearch("L_N1")&&g.Buildings.I("laser")<Math.Max(2,fronts)&&g.CanBuild("laser")){g.Build("laser");return;}if(g.Buildings.I("interceptor")<2+fronts&&g.CanBuild("interceptor")){g.Build("interceptor");return;}foreach(string id in Mid)if(!g.HasResearch(id)&&Buy(id))return;if(g.Wave>=8){int familyCap=(int)Math.Min(12,3+g.Wave/3);foreach(string family in new[]{"interceptor","missile","laser"})if(g.Buildings.I(family)<familyCap&&g.CanBuild(family)&&g.Energy>g.BuildingCost(family).N("energy")+55){g.Build(family);return;}}foreach(string id in Long)if(!g.HasResearch(id)&&Buy(id))return;foreach(string family in new[]{"lab","solar","mine"})if(g.Buildings.I(family)<Math.Min(20,1+g.Wave/3)&&g.CanBuild(family)){g.Build(family);return;}if(b.EmpCooldown<=0&&b.Enemies.Count>=8&&b.UseEmp())actions["emp"]=actions.I("emp")+1;}
 b.StartWave();while(g.Wave<6&&!b.Dead&&time<360){if(time>=nextAction){Act();nextAction=time+1;}g.Tick(1d/30);b.Step(1d/30);time+=1d/30;if(g.Wave!=reported){reported=g.Wave;waves.Add(new DataMap{["wave"]=g.Wave,["earth_hp"]=g.EarthHp,["shield"]=g.Shield,["alive"]=b.Drones.Count,["enemy"]=b.Enemies.Count,["science"]=g.Science,["alien_points"]=g.AlienPoints,["factories"]=g.Buildings.DeepClone(),["seconds"]=time});}}var result=new DataMap{["seed"]=seed,["wave"]=g.Wave,["seconds"]=time,["earth_hp"]=g.EarthHp,["first_perk_wave"]=firstPerk,["missile"]=g.HasResearch("M_N1"),["laser"]=g.HasResearch("L_N1"),["actions"]=actions,["purchases"]=purchases,["waves"]=waves};runs.Add(result);Console.WriteLine("MANAGED_NATURAL "+result.ToJson());}File.WriteAllText("artifacts/csharp-natural-managed.json",new DataMap{["runs"]=runs}.ToJson());var original=DataMap.Parse(File.ReadAllText("artifacts/csharp-natural-gd.json")).List("runs").Cast<DataMap>().ToList();int failures=0;foreach(DataMap row in runs){var reference=original.Single(x=>x.I("seed")==row.I("seed"));var actualPurchases=row.List("purchases").Cast<DataMap>().ToList();var expectedPurchases=reference.List("purchases").Cast<DataMap>().ToList();bool samePurchases=actualPurchases.Count==expectedPurchases.Count&&actualPurchases.Zip(expectedPurchases).All(pair=>pair.First.S("id")==pair.Second.S("id")&&pair.First.L("wave")==pair.Second.L("wave")&&Math.Abs(pair.First.N("time")-pair.Second.N("time"))<.0001&&Math.Abs(pair.First.N("science")-pair.Second.N("science"))<.0001);bool sameActions=row.Map("actions").I("emp")==reference.Map("actions").I("emp")&&row.Map("actions").I("repairs")==reference.Map("actions").I("repairs");bool pass=sameActions&&samePurchases&&Math.Abs(row.N("earth_hp")-reference.N("earth_hp"))<.000001&&row.I("first_perk_wave")==reference.I("first_perk_wave")&&row.I("wave")==6&&row.N("earth_hp")>0&&row.I("first_perk_wave")>=3&&row.I("first_perk_wave")<=5&&row.B("missile")&&Math.Abs(row.N("seconds")-reference.N("seconds"))<.001;Console.WriteLine($"NATURAL_COMPARE seed={row.I("seed")} C#HP={row.N("earth_hp"):0.000} GDHP={reference.N("earth_hp"):0.000} C#firstPerk={row.I("first_perk_wave")} GDfirstPerk={reference.I("first_perk_wave")} pass={pass}");if(!pass)failures++;}Console.WriteLine("NATURAL_OPENING "+(failures==0?"PASS":"FAIL"));System.Environment.ExitCode=failures==0?0:1;}
}


